parameters.inputSchema:
{
 "type": "object",
 "properties": {
  "query": {
   "type": "string",
   "description": "texto a buscar: nombre, empresa, email o telefono"
  }
 },
 "additionalProperties": true
}

parameters.jsCode:
const ws = $('Normalize input').first().json.workspaceId;
const a = (query && typeof query === 'object') ? query : {};
const input = {};
const v = a["query"];
if (v !== undefined && v !== null && String(v).trim() !== '') input["query"] = String(v);
let res;
try {
  res = await this.helpers.httpRequest({
    method: 'POST',
    url: $env.CRM_BASE_URL + '/api/agent/tool',
    headers: { 'x-nowcrm-secret': $env.AGENT_TOOL_SECRET, 'Content-Type': 'application/json' },
    body: { tool: "search_clients", workspace_id: ws, input },
    json: true,
  });
} catch (e) {
  return JSON.stringify({ ok:false, error: 'crm_unreachable', detail: String(e.message||e) });
}
return typeof res === 'string' ? res : JSON.stringify(res);

